// pubspec.yaml: video_player: ^2.9.0
import 'package:video_player/video_player.dart';

class Player extends StatefulWidget {
  const Player({super.key, required this.url});
  final String url;
  @override State<Player> createState() => _PlayerState();
}

class _PlayerState extends State<Player> with WidgetsBindingObserver {
  late VideoPlayerController _controller;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _controller = VideoPlayerController.networkUrl(
      Uri.parse(widget.url),
      videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
    )..initialize().then((_) {
      if (!mounted) return;
      _controller.setLooping(false);
      _controller.play();
      setState(() {});
    })..addListener(_onPlayerState);
  }

  void _onPlayerState() {
    if (_controller.value.hasError) {
      // handle error
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // Pause when app is backgrounded — save battery + avoid audio playing over other apps
    if (state == AppLifecycleState.paused) _controller.pause();
  }

  @override
  Widget build(BuildContext context) {
    if (!_controller.value.isInitialized) return const Center(child: CircularProgressIndicator());
    return Column(children: [
      AspectRatio(
        aspectRatio: _controller.value.aspectRatio,
        child: VideoPlayer(_controller),
      ),
      VideoProgressIndicator(_controller, allowScrubbing: true, colors: const VideoProgressColors(
        playedColor: Colors.red, backgroundColor: Colors.grey, bufferedColor: Colors.blueGrey,
      )),
      Row(children: [
        IconButton(icon: const Icon(Icons.replay_10), onPressed: () =>
          _controller.seekTo(_controller.value.position - const Duration(seconds: 10))),
        IconButton(icon: Icon(_controller.value.isPlaying ? Icons.pause : Icons.play_arrow),
          onPressed: () => _controller.value.isPlaying ? _controller.pause() : _controller.play()),
        IconButton(icon: const Icon(Icons.forward_10), onPressed: () =>
          _controller.seekTo(_controller.value.position + const Duration(seconds: 10))),
      ]),
    ]);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller.removeListener(_onPlayerState);
    _controller.dispose();     // REQUIRED — releases native decoder
    super.dispose();
  }
}
